import pandas as pd


def run(inputs: dict) -> dict:
    dim_price = inputs["dim_price"].copy()
    stg_price = inputs["stg_price"].copy()
    batch_date = inputs["batch_control"]["batch_date"].iloc[0]

    # Build per-product list of version dicts from existing dim_price
    records = {}
    for _, row in dim_price.iterrows():
        records.setdefault(row["product_id"], []).append({
            "product_id": row["product_id"],
            "list_price": row["list_price"],
            "eff_start_date": row["eff_start_date"],
            "eff_end_date": row["eff_end_date"],
        })

    # Process staging rows per product, in effective_date order
    if len(stg_price) > 0:
        for product_id, group in stg_price.groupby("product_id"):
            group = group.sort_values("effective_date")
            versions = records.setdefault(product_id, [])
            for _, s in group.iterrows():
                if versions:
                    tail = max(versions, key=lambda v: v["eff_start_date"])
                else:
                    tail = None

                if tail is not None and tail["list_price"] == s["list_price"]:
                    # unchanged - skip, no new version
                    continue

                if tail is not None:
                    tail["eff_end_date"] = s["effective_date"]

                versions.append({
                    "product_id": product_id,
                    "list_price": s["list_price"],
                    "eff_start_date": s["effective_date"],
                    "eff_end_date": pd.NaT,
                })

    # Flatten all versions
    all_versions = []
    for product_id, versions in records.items():
        for v in versions:
            all_versions.append(v)

    if len(all_versions) == 0:
        out = pd.DataFrame(columns=[
            "product_id", "list_price", "eff_start_date", "eff_end_date", "is_current"
        ])
        out["product_id"] = out["product_id"].astype("int64")
        out["list_price"] = out["list_price"].astype("float64")
        out["eff_start_date"] = pd.to_datetime(out["eff_start_date"])
        out["eff_end_date"] = pd.to_datetime(out["eff_end_date"])
        out["is_current"] = out["is_current"].astype("int64")
        return {"dim_price_out": out}

    out = pd.DataFrame(all_versions)

    def compute_is_current(row):
        start = row["eff_start_date"]
        end = row["eff_end_date"]
        if pd.isna(end):
            return 1 if start <= batch_date else 0
        else:
            return 1 if (start <= batch_date < end) else 0

    out["is_current"] = out.apply(compute_is_current, axis=1)

    out = out[["product_id", "list_price", "eff_start_date", "eff_end_date", "is_current"]]

    out["product_id"] = out["product_id"].astype("int64")
    out["list_price"] = out["list_price"].astype("float64")
    out["eff_start_date"] = pd.to_datetime(out["eff_start_date"])
    out["eff_end_date"] = pd.to_datetime(out["eff_end_date"])
    out["is_current"] = out["is_current"].astype("int64")

    out = out.sort_values(["product_id", "eff_start_date"]).reset_index(drop=True)

    return {"dim_price_out": out}
